package org.jsoup.parser;

import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.junit.Test;

import java.io.Reader;
import java.io.StringReader;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class XmlTreeBuilderTest {

    @Test
    public void parseReaderBaseUriTest() {
        XmlTreeBuilder builder = new XmlTreeBuilder();
        Reader input = new StringReader("<foo></foo>");
        Document document = builder.parse(input, "http://base.uri");
        assertEquals("http://base.uri", document.baseUri());
        assertEquals("foo", document.childNode(0).nodeName());
    }

    @Test
    public void parseStringBaseUriTest() {
        XmlTreeBuilder builder = new XmlTreeBuilder();
        String input = "<foo></foo>";
        Document document = builder.parse(input, "http://base.uri");
        assertEquals("http://base.uri", document.baseUri());
        assertEquals("foo", document.childNode(0).nodeName());
    }

    @Test
    public void newInstanceTest() {
        XmlTreeBuilder builder = new XmlTreeBuilder();
        XmlTreeBuilder instance = builder.newInstance();
        assertTrue(instance instanceof XmlTreeBuilder);
    }

    @Test
    public void insertCommentTokenTest() {
        XmlTreeBuilder builder = new XmlTreeBuilder();
        Token.Comment commentToken = new Token.Comment();
        commentToken.data("Test Comment");
        builder.insert(commentToken);
        Node node = builder.getStack().get(0);
        assertTrue(node instanceof Comment);
        assertEquals("Test Comment", node.attr("data"));
    }

    @Test
    public void insertCharacterTokenTest() {
        XmlTreeBuilder builder = new XmlTreeBuilder();
        Token.Character characterToken = new Token.Character();
        characterToken.data("a");
        builder.insert(characterToken);
        Node node = builder.getStack().get(0);
        assertTrue(node instanceof TextNode);
        assertEquals("a", node.attr("text"));
    }

    @Test
    public void insertDoctypeTokenTest() {
        XmlTreeBuilder builder = new XmlTreeBuilder();
        Token.Doctype doctypeToken = new Token.Doctype();
        doctypeToken.name("html");
        builder.insert(doctypeToken);
        Node node = builder.getStack().get(0);
        assertTrue(node instanceof DocumentType);
        assertEquals("html", ((DocumentType) node).name());
    }

    @Test
    public void parseFragmentInputFragmentBaseUriParserTest() {
        XmlTreeBuilder builder = new XmlTreeBuilder();
        String inputFragment = "<h1>Hello</h1>";
        Parser parser = Parser.xmlParser();
        List<Node> nodes = builder.parseFragment(inputFragment, "http://base.uri", parser);
        assertEquals(1, nodes.size());
        Node node = nodes.get(0);
        assertTrue(node instanceof Element);
        assertEquals("h1", ((Element) node).tagName());
        assertEquals("Hello", ((Element) node).text());
    }
}
